`timescale 1ns/1ps
// Self-checking testbench - generated by scripts/make_experiments.py
// One clock = one model step. Writes stdp_network.csv in the simulator's working directory.
module tb;
    reg clk = 0, rst = 1, en = 1;
    always #5 clk = ~clk;
    integer t, f, errors = 0;
    task check(input [8*24-1:0] what, input integer got, input integer exp);
        begin
            if (exp >= 0 && got !== exp) begin errors = errors + 1; $display("  FAIL %0s: got %0d, expected %0d", what, got, exp); end
            else $display("  ok   %0s = %0d", what, got);
            $display("RESULT %0s=%0d", what, got);
        end
    endtask
    reg [3:0] pre;  reg learn = 1;  wire post;  wire signed [31:0] v;  wire [127:0] w_bus;
    stdp_network dut (.clk(clk), .rst(rst), .en(en), .learn(learn), .pre(pre), .post(post), .v(v), .w_bus(w_bus));
    reg [15:0] l0 = 16'hACE1, l1 = 16'h1234, l2 = 16'hBEEF;
    function [15:0] step(input [15:0] x); step = x[0] ? ((x >> 1) ^ 16'hB400) : (x >> 1); endfunction
    integer w0, w1, w2, w3;
    initial begin
        f = $fopen("stdp_network.csv", "w"); $fdisplay(f, "t,w0,w1,w2,w3");
        pre = 0; repeat (2) @(posedge clk); #1 rst = 0;
        for (t = 0; t < 30000; t = t + 1) begin
            l0 = step(l0); l1 = step(l1); l2 = step(l2);
            pre = {l2 < 16'd4000, l1 < 16'd4000, l0 < 16'd4000, l0 < 16'd4000};
            @(posedge clk); #1;
            if (t % 250 == 0) $fdisplay(f, "%0d,%0d,%0d,%0d,%0d", t, $signed(w_bus[31:0]), $signed(w_bus[63:32]), $signed(w_bus[95:64]), $signed(w_bus[127:96]));
        end
        w0 = $signed(w_bus[31:0]); w1 = $signed(w_bus[63:32]); w2 = $signed(w_bus[95:64]); w3 = $signed(w_bus[127:96]);
        check("w0_final", w0, -1); check("w1_final", w1, -1); check("w2_final", w2, -1); check("w3_final", w3, -1);
        if (!(w0 > 200 && w1 > 200 && w2 < 100 && w3 < 100)) begin errors = errors + 1; $display("  FAIL correlated pair did not win"); end
        else $display("  ok   correlated inputs won (w0, w1 > 200; w2, w3 < 100)");
        if (errors == 0) $display("*** PASS ***"); else $display("*** FAIL: %0d check(s) ***", errors);
        $fclose(f); $finish;
    end
endmodule
